using System.Text.Json;
using Avalonia;
using Avalonia.Controls;
using Avalonia.Input;
using Avalonia.Input.Raw;
using Avalonia.Interactivity;
using Avalonia.VisualTree;
using LtcPlayer.App;
namespace LtcPlayer.Avalonia;
public static class MultiSelectionVerification
{
 public static async Task RunAsync(MainWindow w,string folder)
 {
  Directory.CreateDirectory(folder);var results=new List<object>();bool failed=false;int receiving=0;
  void Check(bool ok,string why){if(!ok)throw new IOException(why);}
  async Task Test(string name,Func<Task> body){try{await body();results.Add(new{test=name,status="PASS"});}catch(Exception e){failed=true;results.Add(new{test=name,status="FAIL",detail=e.ToString()});}File.WriteAllText(Path.Combine(folder,"results.json"),JsonSerializer.Serialize(results,new JsonSerializerOptions{WriteIndented=true}));}
  async Task Until(Func<bool> condition){double end=MasterClock.Timestamp()+10;while(!condition()){if(MasterClock.Timestamp()>end)throw new TimeoutException(JsonSerializer.Serialize(new{w.Preview.Snapshot,w.LatestObservation}));await Task.Delay(10);}}
  var grid=w.FindControl<DataGrid>("CueGrid")!;var delete=w.FindControl<Button>("DeleteCueButton")!;var clone=w.FindControl<Button>("CloneCueButton")!;
  void Select(params CueRow[] rows){grid.SelectedItems.Clear();foreach(var row in rows)grid.SelectedItems.Add(row);}
  Guid[] Selection()=>grid.SelectedItems.OfType<CueRow>().Select(r=>r.CueId).Order().ToArray();
  bool Selected(params CueRow[] rows)=>Selection().SequenceEqual(rows.Select(r=>r.CueId).Order());
  void Click(Control target,KeyModifiers modifiers=KeyModifiers.None){var pointer=new Pointer(9,PointerType.Mouse,true);var point=new Point(target.Bounds.Width/2,target.Bounds.Height/2);target.RaiseEvent(new PointerPressedEventArgs(target,pointer,target,point,0,new PointerPointProperties(RawInputModifiers.LeftMouseButton,PointerUpdateKind.LeftButtonPressed),modifiers,1));target.RaiseEvent(new PointerReleasedEventArgs(target,pointer,target,point,1,new PointerPointProperties(RawInputModifiers.None,PointerUpdateKind.LeftButtonReleased),modifiers,MouseButton.Left));}
  Control FileCell(CueRow row)=>grid.GetVisualDescendants().OfType<TextBlock>().First(t=>t.DataContext==row&&t.Text==row.Name).GetVisualAncestors().OfType<DataGridCell>().First();
  var a=new CueRow{FilePath=Path.Combine(Program.Option("--fixtures")!,"hap-sync-30s.mov")};CueRow b=null!,c=null!,d=null!;
  void Readd(CueRow row){if(!w.Editor.Rows.Contains(row))w.Editor.Add(row);}
  bool Black()=>w.Surface.Canvas.Readback().Where((_,i)=>i%4!=3).All(v=>v==0);
  try{
   await Test("batch removes distinct existing IDs and publishes only final definition once",()=>{var e=new ShowEditor();var x=new CueRow{Duration=5,FrameRate=25,Codec="h264"};var y=new CueRow{Duration=5,FrameRate=25,Codec="h264"};y.SetStart("00:00:10:00");e.Add(x);e.Add(y);int validations=0,published=0;e.Changed+=()=>{validations++;Check(e.Rows.Count==0&&e.Timeline.Length==0,"intermediate definition published");};e.PlaybackChanged+=()=>published++;Check(e.DeleteMany([x.CueId,x.CueId,y.CueId,Guid.NewGuid()])==2&&validations==1&&published==1,"batch repeated validation or publication");return Task.CompletedTask;});
   await Test("empty or obsolete deletion request is a no-op",()=>{var e=new ShowEditor();e.Add(new CueRow());int changes=0;e.Changed+=()=>changes++;Check(e.DeleteMany([])==0&&e.DeleteMany([Guid.NewGuid()])==0&&changes==0&&e.Rows.Count==1,"no-op changed editor");return Task.CompletedTask;});
   await Test("removed rows no longer trigger editor validation",()=>{var e=new ShowEditor();var x=new CueRow();e.Add(x);e.Delete(x);int changes=0;e.Changed+=()=>changes++;x.Seconds="10";Check(changes==0,"removed row subscription retained");return Task.CompletedTask;});
   await Test("editor rejects whole batch when definition is locked",()=>{var e=new ShowEditor();var x=new CueRow();var y=new CueRow();e.Add(x);e.Add(y);e.DefinitionAuthority=()=>false;bool rejected=false;try{e.DeleteMany([x.CueId,y.CueId]);}catch(InvalidOperationException){rejected=true;}Check(rejected&&e.Rows.Count==2,"locked deletion partially applied");return Task.CompletedTask;});
   await Test("maximum-sized list deletes with one validation and final empty definition",()=>{var e=new ShowEditor();for(int n=0;n<1000;n++)e.Add(new CueRow{Enabled=false});int changes=0;e.Changed+=()=>changes++;var ids=e.Rows.Select(r=>r.CueId).ToArray();Check(e.DeleteMany(ids)==1000&&changes==1&&e.Rows.Count==0&&e.Timeline.Length==0,"large batch published intermediate states");return Task.CompletedTask;});
   await w.ApplySettingsAsync(new(new(Rate:"25"),VideoRenderer.Displays().First(r=>r.Primary!=0)));await ShowProgramService.RefreshAsync(a,CancellationToken.None);b=a.CloneDisabled();b.Enabled=true;b.SetStart("00:00:10:00");c=a.CloneDisabled();c.Enabled=true;c.SetStart("00:00:20:00");d=a.CloneDisabled();d.SetStart("00:00:25:00");foreach(var row in new[]{a,b,c,d})w.Editor.Add(row);await Task.Delay(180);
   await Test("normal Ctrl and Shift clicks select expected row sets",async()=>{Click(FileCell(a));Check(Selected(a),"normal click failed");Click(FileCell(c),KeyModifiers.Control);Check(Selected(a,c),"Ctrl add failed");Click(FileCell(a),KeyModifiers.Control);Check(Selected(c),"Ctrl remove failed");Click(FileCell(a));Click(FileCell(c),KeyModifiers.Shift);await Task.Delay(30);Check(Selected(a,b,c),"Shift range failed");});
   await Test("empty single and multiple selection drive delete and clone permission",()=>{Select();Check(!delete.IsEnabled&&!clone.IsEnabled,"empty commands enabled");Select(a);Check(delete.IsEnabled&&clone.IsEnabled&&delete.Content?.ToString()=="削除","single state wrong");Select(a,c);Check(delete.IsEnabled&&!clone.IsEnabled&&delete.Content?.ToString()=="削除","multi state wrong");return Task.CompletedTask;});
   await Test("multiple selection cannot trigger implicit single-row cloning",async()=>{Select(a,b);int count=w.Editor.Rows.Count;clone.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(20);Check(w.Editor.Rows.Count==count&&Selected(a,b),"ambiguous clone executed");});
   await w.SetSharedAudioAsync(true,silenceForVerification:true);await w.PlayCueForTestAsync(a);await Until(()=>w.Coordinator.Audio.State==SharedAudioState.Playing);
   await Test("selection and row play leave selection separate from actual playback",async()=>{Select(b,c);var video=w.Preview.PlaybackSessionId;int preps=w.Coordinator.Audio.PreparationStarts;long builds=w.Preview.IndexCache.Builds;await Task.Delay(80);Check(w.Preview.PlaybackSessionId==video&&w.Coordinator.Audio.PreparationStarts==preps&&w.Preview.IndexCache.Builds==builds,"selection prepared media");await w.PlayCueForTestAsync(a);Check(Selected(b,c)&&w.Preview.Snapshot.State==PreviewState.Paused,"play inferred selection or collapsed it");await w.PlayCueForTestAsync(a);});
   await Test("actual row play button targets its row while retaining multiple selection",async()=>{Select(b,c);var play=grid.GetVisualDescendants().OfType<Button>().First(x=>x.DataContext==a&&x.Classes.Contains("cue-play"));Click(play);await Until(()=>w.Preview.Snapshot.State==PreviewState.Paused);Check(Selected(b,c),"row play collapsed selection");Click(play);await Until(()=>w.Preview.Snapshot.State==PreviewState.Playing);});
   await Test("reordering one row preserves multiple selected IDs and playback",()=>{var video=w.Preview.PlaybackSessionId;Select(b,c);w.MoveCue(d,1);Check(Selected(b,c)&&w.Editor.Rows[1]==d&&w.Preview.PlaybackSessionId==video,"move lost selection or altered playback");return Task.CompletedTask;});
   await Test("unrelated batch deletion with output off preserves video audio and publishes once",async()=>{Select(b,c);var video=w.Preview.PlaybackSessionId;var sink=w.Coordinator.Audio.SinkSession;int changed=0;void Changed()=>changed++;w.Editor.Changed+=Changed;try{await w.DeleteCuesAsync([b.CueId,c.CueId]);}finally{w.Editor.Changed-=Changed;}Check(!w.Editor.Rows.Contains(b)&&!w.Editor.Rows.Contains(c)&&w.Preview.PlaybackSessionId==video&&w.Coordinator.Audio.SinkSession==sink&&changed==1,"unrelated batch interrupted or repeated validation");});
   Readd(b);Readd(c);
   await Test("deleting subset preserves surviving selection and nearby fallback never starts playback",async()=>{Select(b,c);var video=w.Preview.PlaybackSessionId;await w.DeleteCuesAsync([b.CueId]);Check(Selected(c)&&w.Preview.PlaybackSessionId==video,"surviving selection lost");await w.DeleteCuesAsync([c.CueId]);Check(grid.SelectedItems.Count==1&&w.Editor.Rows.Contains((CueRow)grid.SelectedItem!)&&w.Preview.PlaybackSessionId==video,"fallback selected missing row or changed source");});
   Readd(b);Readd(c);await w.ArmAsync();
   await Test("unrelated batch deletion with output on keeps persistent canvas and audio",async()=>{var video=w.Preview.PlaybackSessionId;var canvas=w.Surface.Canvas.SessionId;var sink=w.Coordinator.Audio.SinkSession;await w.DeleteCuesAsync([b.CueId,c.CueId]);Check(w.IsOutputActive&&w.Surface.Canvas.SessionId==canvas&&w.Preview.PlaybackSessionId==video&&w.Coordinator.Audio.SinkSession==sink,"external output or playback reset");});
   Readd(b);Readd(c);
   await Test("deleting playing source and another row clears once with cover and output retained",async()=>{Select(a,b);w.SetFadeSeconds(0);w.SetCoverVisible(true);int generation=w.Preview.SourceGeneration;var canvas=w.Surface.Canvas.SessionId;await w.DeleteCuesAsync([a.CueId,b.CueId,a.CueId]);await Until(()=>w.Coordinator.Audio.State==SharedAudioState.Waiting);Check(!w.Editor.Rows.Contains(a)&&!w.Editor.Rows.Contains(b)&&w.Preview.SourceGeneration==generation+1&&w.Preview.LoadedPath==""&&w.Cover.IsCovered&&w.IsOutputActive&&w.Surface.Canvas.SessionId==canvas,"source cleared multiple times or resources lost");w.SetCoverVisible(false);Check(Black(),"delete not black");});
   Readd(a);Readd(b);await w.PlayCueForTestAsync(a);await w.PlayCueForTestAsync(a);
   await Test("paused source follows same batch deletion contract",async()=>{Check(w.Preview.Snapshot.State==PreviewState.Paused,"not paused");await w.DeleteCuesAsync([a.CueId,b.CueId]);Check(w.Preview.Snapshot.State==PreviewState.Empty&&Black()&&!w.Editor.Rows.Contains(a)&&!w.Editor.Rows.Contains(b),"paused source retained");});
   Readd(a);Readd(b);await w.PlayCueForTestAsync(a);await w.Preview.StopAsync();
   await Test("stopped source follows same batch deletion contract",async()=>{Check(w.Preview.Snapshot.State==PreviewState.Stopped,"not stopped");await w.DeleteCuesAsync([a.CueId,b.CueId]);Check(w.Preview.Snapshot.State==PreviewState.Empty&&Black(),"stopped source retained");});
   Readd(a);Readd(b);await w.Monitor.ConfigureAsync(new(Rate:"25"),async(clock,t)=>{while(!t.IsCancellationRequested){if(Volatile.Read(ref receiving)!=0)clock.Accept(new TcFrame{Seconds=1},MasterClock.Timestamp());await Task.Delay(20,t);}});Volatile.Write(ref receiving,1);await Until(()=>w.LatestObservation?.CueId==a.CueId&&w.Coordinator.OwnsSurface);
   await Test("live LTC prohibits batch deletion and disables selected commands",async()=>{Select(a,b);await w.DeleteCuesAsync([a.CueId,b.CueId]);Check(w.Editor.Rows.Contains(a)&&w.Editor.Rows.Contains(b)&&!delete.IsEnabled&&!clone.IsEnabled,"live deletion allowed");});
   Volatile.Write(ref receiving,0);await Until(()=>w.Monitor.Clock.Read().State==SyncState.LOST);await Task.Delay(100);
   await Test("unrelated LOST batch keeps exact held frame and synchronization session",async()=>{var sync=w.SynchronizationSession;var pixels=w.Surface.Canvas.Readback();await w.DeleteCuesAsync([b.CueId,c.CueId]);Check(w.SynchronizationSession==sync&&pixels.AsSpan().SequenceEqual(w.Surface.Canvas.Readback())&&w.Editor.Rows.Contains(a),"unrelated LOST delete cleared hold");});
   Readd(b);Readd(c);
   await Test("LTC resumption during held-source release cancels entire batch",async()=>{w.Coordinator.BeforeHeldClearForTest=async()=>{Volatile.Write(ref receiving,1);await Until(()=>w.Monitor.Clock.Read().State is SyncState.LOCKED or SyncState.RESYNC);};try{await w.DeleteCuesAsync([a.CueId,b.CueId]);}finally{w.Coordinator.BeforeHeldClearForTest=null;}Check(w.Editor.Rows.Contains(a)&&w.Editor.Rows.Contains(b),"partial deletion on LTC resumption");await Until(()=>w.Coordinator.OwnsSurface&&w.LatestObservation?.CueId==a.CueId);});
   Volatile.Write(ref receiving,0);await Until(()=>w.Monitor.Clock.Read().State==SyncState.LOST);await Task.Delay(100);
   await Test("held-source batch clears to black and silence once without losing output",async()=>{int generation=w.Preview.SourceGeneration;var canvas=w.Surface.Canvas.SessionId;Select(a,b);await w.DeleteCuesAsync([a.CueId,b.CueId]);await Until(()=>w.Coordinator.Audio.State==SharedAudioState.Waiting);Check(!w.Editor.Rows.Contains(a)&&!w.Editor.Rows.Contains(b)&&!w.Coordinator.OwnsSurface&&w.Preview.SourceGeneration==generation+1&&Black()&&w.IsOutputActive&&w.Surface.Canvas.SessionId==canvas,"held batch contract broken");});
   await Test("delete button executes whole selected batch and leaves empty commands disabled",async()=>{Select(w.Editor.Rows.ToArray());delete.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Until(()=>w.Editor.Rows.Count==0);Check(!delete.IsEnabled&&!clone.IsEnabled&&grid.SelectedItems.Count==0&&w.Editor.Timeline.Length==0,"button deleted only one row or left stale selection");});
  }catch(Exception e){failed=true;File.WriteAllText(Path.Combine(folder,"fatal.txt"),e.ToString());}
  finally{w.Coordinator.BeforeHeldClearForTest=null;Volatile.Write(ref receiving,0);await w.DisarmAsync();await w.Coordinator.DisposeAsync();await w.Preview.DisposeAsync();await w.Monitor.DisposeAsync();MainWindow.Shutdown(failed?1:0);}
 }
}
